18	package org.keycloak.services.util;
19	
20	import jakarta.ws.rs.core.UriBuilder;
21	
22	import org.keycloak.common.util.StringPropertyReplacer;
23	import org.keycloak.models.Constants;
24	import org.keycloak.models.KeycloakSession;
25	import org.keycloak.urls.UrlType;
26	
27	/**
28	 * @author <a href="mailto:bill@burkecentral.com">Bill Burke</a>
29	 * @version $Revision: 1 $
30	 */
31	public class ResolveRelative {
32	
33	    public static String resolveRelativeUri(KeycloakSession session, String rootUrl, String url) {
34	        String frontendUrl = session.getContext().getUri(UrlType.FRONTEND).getBaseUri().toString();
35	        String adminUrl = session.getContext().getUri(UrlType.ADMIN).getBaseUri().toString();
36	        return resolveRelativeUri(frontendUrl, adminUrl, rootUrl, url);
37	    }
38	
39	    public static String resolveRelativeUri(String frontendUrl, String adminUrl, String rootUrl, String url) {
40	        String finalUrl;
41	
42	        if (url == null || !url.startsWith("/")) {
43	            finalUrl = url;
44	        } else if (rootUrl != null && !rootUrl.isEmpty()) {
45	            finalUrl = resolveRootUrl(frontendUrl, adminUrl, rootUrl) + url;
46	        } else {
47	            finalUrl = UriBuilder.fromUri(frontendUrl).replacePath(url).build().toString();
48	        }
49	
50	        return StringPropertyReplacer.replaceProperties(finalUrl);
51	    }
52	
53	    public static String resolveRootUrl(KeycloakSession session, String rootUrl) {
54	        String frontendUrl = session.getContext().getUri(UrlType.FRONTEND).getBaseUri().toString();
55	        String adminUrl = session.getContext().getUri(UrlType.ADMIN).getBaseUri().toString();
56	        return resolveRootUrl(frontendUrl, adminUrl, rootUrl);
57	    }
58	
59	    public static String resolveRootUrl(String frontendUrl, String adminUrl, String rootUrl) {
60	        if (rootUrl != null) {
61	            if (rootUrl.equals(Constants.AUTH_BASE_URL_PROP)) {
62	                rootUrl = frontendUrl;
63	                if (rootUrl.endsWith("/")) {
64	                    rootUrl = rootUrl.substring(0, rootUrl.length() - 1);
65	                }
66	            } else if (rootUrl.equals(Constants.AUTH_ADMIN_URL_PROP)) {
67	                rootUrl = adminUrl;
68	                if (rootUrl.endsWith("/")) {
69	                    rootUrl = rootUrl.substring(0, rootUrl.length() - 1);
70	                }
71	            }
72	        }
73	        return rootUrl;
74	    }
75	}
