18	package org.keycloak.services.util;
19	
20	import java.net.URI;
21	import java.util.regex.Matcher;
22	import java.util.regex.Pattern;
23	
24	import jakarta.ws.rs.core.Response;
25	
26	import org.keycloak.http.HttpRequest;
27	import org.keycloak.models.KeycloakSession;
28	import org.keycloak.sessions.AuthenticationSessionModel;
29	import org.keycloak.utils.MediaType;
