33	/**
34	 * The point of this is to improve experience of browser history (back/forward/refresh buttons), but ensure there is no more redirects then necessary.
35	 *
36	 * Ideally we want to:
37	 * - Remove all POST requests from browser history, because browsers don't automatically re-send them when click "back" button. POSTS in history causes unfriendly dialogs and browser "Page is expired" pages.
38	 *
39	 * - Keep the browser URL to match the flow and execution from authentication session. This means that browser refresh works fine and show us the correct form.
40	 *
41	 * - Avoid redirects. This is possible with javascript based approach (JavascriptHistoryReplace). The RedirectAfterPostHelper requires one redirect after POST, but works even on browser without javascript and
42	 * on old browsers where "history.replaceState" is unsupported.
43	 *
44	 * @author <a href="mailto:mposolda@redhat.com">Marek Posolda</a>
45	 */
46	public abstract class BrowserHistoryHelper {
47	
48	    // Request attribute, which specifies if flow was changed in this request (eg. click "register" from the login screen)
49	    public static final String SHOULD_UPDATE_BROWSER_HISTORY = "SHOULD_UPDATE_BROWSER_HISTORY";
50	
51	    protected static final Logger logger = Logger.getLogger(BrowserHistoryHelper.class);
52	
53	    public abstract Response saveResponseAndRedirect(KeycloakSession session, AuthenticationSessionModel authSession, Response response, boolean actionRequest, HttpRequest httpRequest);
54	
55	    public abstract Response loadSavedResponse(KeycloakSession session, AuthenticationSessionModel authSession);
56	
57	
58	    protected boolean shouldReplaceBrowserHistory(boolean actionRequest, KeycloakSession session) {
59	        if (actionRequest) {
60	            return true;
61	        }
62	
63	        Boolean flowChanged = (Boolean) session.getAttribute(SHOULD_UPDATE_BROWSER_HISTORY);
64	        return (flowChanged != null && flowChanged);
65	    }
66	
67	
68	
69	    // Always rely on javascript for now
70	    public static BrowserHistoryHelper getInstance() {
71	        return new JavascriptHistoryReplace();
72	        //return new RedirectAfterPostHelper();
73	        //return new NoOpHelper();
74	    }
75	
76	
77	    // IMPL
78	
79	    private static class JavascriptHistoryReplace extends BrowserHistoryHelper {
80	
81	        private static final Pattern HEAD_END_PATTERN = Pattern.compile("</[hH][eE][aA][dD]>");
82	
83	        @Override
84	        public Response saveResponseAndRedirect(KeycloakSession session, AuthenticationSessionModel authSession, Response response, boolean actionRequest, HttpRequest httpRequest) {
85	            if (!shouldReplaceBrowserHistory(actionRequest, session)) {
86	                return response;
87	            }
88	
89	            // For now, handle just status 200 with String body. See if more is needed...
90	            Object entity = response.getEntity();
91	            if (entity != null && entity instanceof String) {
92	                String responseString = (String) entity;
93	
94	                URI lastExecutionURL = new AuthenticationFlowURLHelper(session, session.getContext().getRealm(), session.getContext().getUri()).getLastExecutionUrl(authSession);
95	
96	                // Inject javascript for history "replaceState"
97	                String responseWithJavascript = responseWithJavascript(responseString, lastExecutionURL.toString());
98	
99	                return Response.fromResponse(response).entity(responseWithJavascript).build();
100	            }
101	
102	
103	            return response;
104	        }
105	
106	        @Override
107	        public Response loadSavedResponse(KeycloakSession session, AuthenticationSessionModel authSession) {
108	            return null;
109	        }
110	
111	
112	        private String responseWithJavascript(String origHtml, String lastExecutionUrl) {
113	            Matcher m = HEAD_END_PATTERN.matcher(origHtml);
114	
115	            if (m.find()) {
116	                int start = m.start();
117	
118	                String javascript = getJavascriptText(lastExecutionUrl);
119	
120	                return new StringBuilder(origHtml.substring(0, start))
121	                        .append(javascript )
122	                        .append(origHtml.substring(start))
123	                        .toString();
124	            } else {
125	                return origHtml;
126	            }
127	        }
128	
129	        private String getJavascriptText(String lastExecutionUrl) {
130	            return new StringBuilder("<SCRIPT>")
131	                    .append(" if (typeof history.replaceState === 'function') {")
132	                    .append("  history.replaceState({}, \"some title\", \"" + lastExecutionUrl + "\");")
133	                    .append(" }")
134	                    .append("</SCRIPT>")
135	                    .toString();
136	        }
137	
138	    }
139	
140	
141	    // This impl is limited ATM. Saved request doesn't save response HTTP headers, so they may not be fully restored..
142	    private static class RedirectAfterPostHelper extends BrowserHistoryHelper {
143	
144	        private static final String CACHED_RESPONSE = "cached.response";
145	
146	        @Override
147	        public Response saveResponseAndRedirect(KeycloakSession session, AuthenticationSessionModel authSession, Response response, boolean actionRequest, HttpRequest httpRequest) {
148	            if (!shouldReplaceBrowserHistory(actionRequest, session)) {
149	                return response;
150	            }
151	
152	            // For now, handle just status 200 with String body. See if more is needed...
153	            if (response.getStatus() == 200) {
154	                Object entity = response.getEntity();
155	                if (entity instanceof String) {
156	                    String responseString = (String) entity;
157	                    authSession.setAuthNote(CACHED_RESPONSE, responseString);
158	
159	                    URI lastExecutionURL = new AuthenticationFlowURLHelper(session, session.getContext().getRealm(), session.getContext().getUri()).getLastExecutionUrl(authSession);
160	
161	                    if (logger.isTraceEnabled()) {
162	                        logger.tracef("Saved response challenge and redirect to %s", lastExecutionURL);
163	                    }
164	
165	                    return Response.status(302).location(lastExecutionURL).build();
166	                }
167	            }
168	
169	            return response;
170	        }
171	
172	
173	        @Override
174	        public Response loadSavedResponse(KeycloakSession session, AuthenticationSessionModel authSession) {
175	            String savedResponse = authSession.getAuthNote(CACHED_RESPONSE);
176	            if (savedResponse != null) {
177	                authSession.removeAuthNote(CACHED_RESPONSE);
178	
179	                if (logger.isTraceEnabled()) {
180	                    logger.tracef("Restored previously saved request");
181	                }
182	
183	                Response.ResponseBuilder builder = Response.status(200).type(MediaType.TEXT_HTML_UTF_8).entity(savedResponse);
184	                return builder.build();
185	            }
186	
187	            return null;
188	        }
189	
190	    }
191	
192	
193	    private static class NoOpHelper extends BrowserHistoryHelper {
194	
195	        @Override
196	        public Response saveResponseAndRedirect(KeycloakSession session, AuthenticationSessionModel authSession, Response response, boolean actionRequest, HttpRequest httpRequest) {
197	            return response;
198	        }
199	
200	
201	        @Override
202	        public Response loadSavedResponse(KeycloakSession session, AuthenticationSessionModel authSession) {
203	            return null;
204	        }
205	
206	    }
207	}
