19	package org.keycloak.services.util;
20	
21	import java.io.IOException;
22	import java.util.ArrayList;
23	import java.util.LinkedHashMap;
24	import java.util.LinkedHashSet;
25	import java.util.List;
26	import java.util.ListIterator;
27	import java.util.Locale;
28	import java.util.Map;
29	import java.util.Properties;
30	import java.util.Set;
31	
32	import org.keycloak.locale.DefaultLocaleSelectorProvider;
33	import org.keycloak.locale.LocaleSelectorProvider;
34	import org.keycloak.locale.LocaleUpdaterProvider;
35	import org.keycloak.models.KeycloakSession;
36	import org.keycloak.models.RealmModel;
37	import org.keycloak.sessions.AuthenticationSessionModel;
38	import org.keycloak.theme.Theme;
39	
40	import org.jboss.logging.Logger;
41	
42	/**
43	 * @author <a href="mailto:mposolda@redhat.com">Marek Posolda</a>
44	 * @author <a href="mailto:daniel.fesenmeyer@bosch.com">Daniel Fesenmeyer</a>
45	 */
46	public class LocaleUtil {
47	
48	    private static final Logger logger = Logger.getLogger(LocaleUtil.class);
49	
50	    private LocaleUtil() {
51	        // noop
52	    }
53	
54	    public static void processLocaleParam(KeycloakSession session, RealmModel realm, AuthenticationSessionModel authSession) {
55	        if (realm.isInternationalizationEnabled()) {
56	            String locale = session.getContext().getUri().getQueryParameters().getFirst(LocaleSelectorProvider.KC_LOCALE_PARAM);
57	            if (locale != null && realm.getSupportedLocalesStream().anyMatch(l -> locale.equals(l))) {
58	                if (authSession != null) {
59	                    authSession.setAuthNote(LocaleSelectorProvider.USER_REQUEST_LOCALE, locale);
60	                } else {
61	                    // Might be on info/error page when we don't have authenticationSession
62	                    session.setAttribute(LocaleSelectorProvider.USER_REQUEST_LOCALE, locale);
63	                }
64	
65	                LocaleUpdaterProvider localeUpdater = session.getProvider(LocaleUpdaterProvider.class);
66	                localeUpdater.updateLocaleCookie(locale);
67	            }
68	        }
69	    }
70	
71	    /**
72	     * Resolves a language tag received from a client to a locale the server is prepared to serve messages for.
73	     * <p>
74	     * The requested tag is matched against the locales declared by the theme, the locales supported by the realm and
75	     * the realm default locale. Only a locale from that bounded, server-controlled set is ever returned, so a client
76	     * cannot introduce arbitrary locales into the caches which are keyed by locale. A tag without a match resolves to
77	     * the realm default locale, or to {@link Locale#ENGLISH}, rather than being rejected, so that clients still
78	     * requesting a locale which has meanwhile been removed from the realm keep receiving usable content.
79	     *
80	     * @param realm the realm
81	     * @param theme the theme whose messages are looked up, may be {@code null}
82	     * @param localeString the requested language tag, may be {@code null}
83	     * @return a supported locale, never {@code null}
84	     */
85	    public static Locale resolveSupportedLocale(RealmModel realm, Theme theme, String localeString) {
86	        Locale match = DefaultLocaleSelectorProvider.findBestMatchingLocale(getSupportedLocales(realm, theme),
87	                localeString);
88	
89	        return match != null ? match : getFallbackLocale(realm);
90	    }
91	
92	    /**
93	     * Returns the locales which may be used to look up messages, which is the union of the locales declared by the
94	     * theme, the locales supported by the realm and the fallback locale.
95	     */
96	    private static List<Locale> getSupportedLocales(RealmModel realm, Theme theme) {
97	        Set<Locale> supportedLocales = new LinkedHashSet<>();
98	
99	        if (theme != null) {
100	            try {
101	                for (String themeLocale : theme.getProperties().getProperty("locales", "").split(",")) {
102	                    themeLocale = themeLocale.trim();
103	                    if (!themeLocale.isEmpty()) {
104	                        supportedLocales.add(Locale.forLanguageTag(themeLocale));
105	                    }
106	                }
107	            } catch (IOException e) {
108	                logger.warn("Failed to read the locales supported by the theme", e);
109	            }
110	        }
111	
112	        realm.getSupportedLocalesStream().map(Locale::forLanguageTag).forEach(supportedLocales::add);
113	        supportedLocales.add(getFallbackLocale(realm));
114	
115	        return new ArrayList<>(supportedLocales);
116	    }
117	
118	    private static Locale getFallbackLocale(RealmModel realm) {
119	        if (realm.isInternationalizationEnabled() && realm.getDefaultLocale() != null) {
120	            return Locale.forLanguageTag(realm.getDefaultLocale());
121	        }
122	
123	        return Locale.ENGLISH;
124	    }
125	
126	    /**
127	     * Returns the parent locale of the given {@code locale}. If the locale just contains a language (e.g. "de"),
128	     * returns the fallback locale "en". For "en" no parent exists, {@code null} is returned.
129	     *
130	     * @param locale the locale
131	     * @return the parent locale, may be {@code null}
132	     * @deprecated use {@link LocaleUtil#getParentLocale(Locale, RealmModel)} instead.
133	     */
134	    @Deprecated(since = "26.5", forRemoval = true)
135	    public static Locale getParentLocale(Locale locale) {
136	        return getParentLocale(locale, null);
137	    }
138	
139	    /**
140	     * Returns the parent locale of the given {@code locale}. If the locale just contains a language (e.g. "de"),
141	     * returns the fallback default locale of the realm or if that does not exist "en".
142	     * For "en" no parent exists, {@code null} is returned.
143	     *
144	     * @return the parent locale, may be {@code null}
145	     */
146	    public static Locale getParentLocale(Locale locale, RealmModel realm) {
147	        if (Locale.ENGLISH.equals(locale)) {
148	            return null;
149	        }
150	
151	        if (locale.getVariant() != null && !locale.getVariant().isEmpty()) {
152	            return new Locale(locale.getLanguage(), locale.getCountry());
153	        }
154	
155	        if (locale.getCountry() != null && !locale.getCountry().isEmpty()) {
156	            return new Locale(locale.getLanguage());
157	        }
158	
159	        if (realm != null
160	                && realm.isInternationalizationEnabled()
161	                && realm.getDefaultLocale() != null
162	                && Locale.forLanguageTag(realm.getDefaultLocale()).getLanguage().equals(locale.getLanguage())) {
163	            return Locale.ENGLISH;
164	        }
165	
166	        if (realm != null
167	                && realm.isInternationalizationEnabled()
168	                && realm.getDefaultLocale() != null) {
169	            return Locale.forLanguageTag(realm.getDefaultLocale());
170	        }
171	
172	        return Locale.ENGLISH;
173	    }
174	
175	    /**
176	     * Gets the applicable locales for the given locale.
177	     * <p>
178	     * Example: Locale "de-CH" has the applicable locales "de-CH", "de" and "en" (in exactly that order).
179	     * 
180	     * @param locale the locale
181	     * @return the applicable locales
182	     */
183	    static List<Locale> getApplicableLocales(Locale locale, RealmModel realm) {
184	        List<Locale> applicableLocales = new ArrayList<>();
185	
186	        for (Locale currentLocale = locale; currentLocale != null; currentLocale = getParentLocale(currentLocale, realm)) {
187	            applicableLocales.add(currentLocale);
188	        }
189	
190	        return applicableLocales;
191	    }
192	
193	    /**
194	     * Merge the given (locale-)grouped messages into one instance of {@link Properties}, applicable for the given
195	     * {@code locale}.
196	     * 
197	     * @param locale the locale
198	     * @param messages the (locale-)grouped messages
199	     * @return the merged properties
200	     * @see #mergeGroupedMessages(RealmModel, Locale, Map, Map)
201	     */
202	    public static Properties mergeGroupedMessages(RealmModel realm, Locale locale, Map<Locale, Properties> messages) {
203	        return mergeGroupedMessages(realm, locale, messages, null);
204	    }
205	
206	    /**
207	     * Merge the given (locale-)grouped messages into one instance of {@link Properties}, applicable for the given
208	     * {@code locale}.
209	     * <p>
210	     * The priority of the messages is as follows (abbreviations: F = firstMessages, S = secondMessages):
211	     * <ol>
212	     * <li>F &lt;language-region-variant&gt;</li>
213	     * <li>S &lt;language-region-variant&gt;</li>
214	     * <li>F &lt;language-region&gt;</li>
215	     * <li>S &lt;language-region&gt;</li>
216	     * <li>F &lt;language&gt;</li>
217	     * <li>S &lt;language&gt;</li>
218	     * <li>F en</li>
219	     * <li>S en</li>
220	     * </ol>
221	     * <p>
222	     * Example for the message priority for locale "de-CH-1996" (language "de", region "CH", variant "1996):
223	     * <ol>
224	     * <li>F de-CH-1996</li>
225	     * <li>S de-CH-1996</li>
226	     * <li>F de-CH</li>
227	     * <li>S de-CH</li>
228	     * <li>F de</li>
229	     * <li>S de</li>
230	     * <li>F en</li>
231	     * <li>S en</li>
232	     * </ol>
233	     * 
234	     * @param locale the locale
235	     * @param firstMessages the first (locale-)grouped messages, having higher priority (per locale) than
236	     *        {@code secondMessages}
237	     * @param secondMessages may be {@code null}, the second (locale-)grouped messages, having lower priority (per
238	     *        locale) than {@code firstMessages}
239	     * @return the merged properties
240	     * @see #mergeGroupedMessages(RealmModel, Locale, Map)
241	     */
242	    public static Properties mergeGroupedMessages(RealmModel realm, Locale locale, Map<Locale, Properties> firstMessages,
243	            Map<Locale, Properties> secondMessages) {
244	        List<Locale> applicableLocales = getApplicableLocales(locale, realm);
245	
246	        Properties mergedProperties = new Properties();
247	
248	        /*
249	         * iterate starting from the end of the list in order to add the least relevant messages first (in order to be
250	         * overwritten by more relevant messages)
251	         */
252	        ListIterator<Locale> itr = applicableLocales.listIterator(applicableLocales.size());
253	        while (itr.hasPrevious()) {
254	            Locale currentLocale = itr.previous();
255	
256	            // add secondMessages first, if specified (to be overwritten by firstMessages)
257	            if (secondMessages != null) {
258	                Properties currentLocaleSecondMessages = secondMessages.get(currentLocale);
259	                if (currentLocaleSecondMessages != null) {
260	                    mergedProperties.putAll(currentLocaleSecondMessages);
261	                }
262	            }
263	
264	            // add firstMessages, overwriting secondMessages (if specified)
265	            Properties currentLocaleFirstMessages = firstMessages.get(currentLocale);
266	            if (currentLocaleFirstMessages != null) {
267	                mergedProperties.putAll(currentLocaleFirstMessages);
268	            }
269	        }
270	
271	        return mergedProperties;
272	    }
273	
274	    /**
275	     * Enhance the properties from a theme with realm localization texts. Realm localization texts take precedence over
276	     * the theme properties, but only when defined for the same locale. In general, texts for a more specific locale
277	     * take precedence over texts for a less specific locale.
278	     * <p>
279	     * For implementation details, see {@link #mergeGroupedMessages(RealmModel, Locale, Map, Map)}.
280	     * 
281	     * @param realm the realm from which the localization texts should be used
282	     * @param locale the locale for which the relevant texts should be retrieved
283	     * @param themeMessages the theme messages, which should be enhanced and maybe overwritten
284	     * @return the enhanced properties
285	     */
286	    public static Properties enhancePropertiesWithRealmLocalizationTexts(RealmModel realm, Locale locale,
287	            Map<Locale, Properties> themeMessages) {
288	        Map<Locale, Properties> realmLocalizationMessages = getRealmLocalizationTexts(realm, locale);
289	
290	        return mergeGroupedMessages(realm, locale, realmLocalizationMessages, themeMessages);
291	    }
292	
293	    public static Map<Locale, Properties> getRealmLocalizationTexts(RealmModel realm, Locale locale) {
294	        LinkedHashMap<Locale, Properties> groupedMessages = new LinkedHashMap<>();
295	
296	        List<Locale> applicableLocales = getApplicableLocales(locale, realm);
297	        for (Locale applicableLocale : applicableLocales) {
298	            Map<String, String> currentRealmLocalizationTexts =
299	                    realm.getRealmLocalizationTextsByLocale(applicableLocale.toLanguageTag());
300	            Properties currentMessages = new Properties();
301	            currentMessages.putAll(currentRealmLocalizationTexts);
302	
303	            groupedMessages.put(applicableLocale, currentMessages);
304	        }
305	
306	        return groupedMessages;
307	    }
308	    
309	}
