36	 */
37	public class HardcodedLDAPAttributeMapper extends AbstractLDAPStorageMapper {
38	
39	    private static final Logger logger = Logger.getLogger(HardcodedLDAPAttributeMapper.class);
40	
41	    public static final String LDAP_ATTRIBUTE_NAME = "ldap.attribute.name";
42	
43	    public static final String LDAP_ATTRIBUTE_VALUE = "ldap.attribute.value";
44	
45	    private static final String RANDOM = "RANDOM";
46	
47	    /**
48	     * When this is configured as LDAP_ATTRIBUTE_VALUE, the mapper will use randomly generated value
49	     */
50	    public static final String RANDOM_ATTRIBUTE_VALUE = "${" + RANDOM + "}";
51	
52	    public static Pattern substitution = Pattern.compile("\\$\\{([^}]+)\\}");
53	
54	    public HardcodedLDAPAttributeMapper(ComponentModel mapperModel, LDAPStorageProvider ldapProvider) {
55	        super(mapperModel, ldapProvider);
56	    }
57	
58	
59	    @Override
60	    public void onRegisterUserToLDAP(LDAPObject ldapUser, UserModel localUser, RealmModel realm) {
61	        String ldapAttrName = mapperModel.get(LDAP_ATTRIBUTE_NAME);
62	        String ldapAttrValue = mapperModel.get(LDAP_ATTRIBUTE_VALUE);
63	
64	        String computedValue = computeAttributeValue(ldapAttrName, ldapAttrValue, ldapUser, localUser, realm);
65	
66	        ldapUser.setAttribute(ldapAttrName, Collections.singleton(computedValue));
67	    }
68	
69	
70	    protected String computeAttributeValue(String ldapAttrName, String ldapAttrValue, LDAPObject ldapUser, UserModel localUser, RealmModel realm) {
71	        Matcher m = substitution.matcher(ldapAttrValue);
72	        StringBuffer sb = new StringBuffer();
73	
74	        while (m.find()) {
75	            String token = m.group(1);
76	            if (token.equals(RANDOM)) {
77	                String randomVal = getRandomValue();
78	                m.appendReplacement(sb, randomVal);
79	            } else {
80	                m.appendReplacement(sb, token);
81	            }
82	        }
83	
84	        m.appendTail(sb);
85	
86	        return sb.toString();
87	    }
88	
89	
90	    private static final String CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVW1234567890";
91	
92	    // Generate random character of length 30. Allowed chars are from range 33-126
93	    protected String getRandomValue() {
94	        SecureRandom r = new SecureRandom();
95	        StringBuilder sb = new StringBuilder();
96	        for (int i = 0; i < 30; i++) {
97	            char c = CHARS.charAt(r.nextInt(CHARS.length()));
98	            sb.append(c);
99	        }
100	        return sb.toString();
101	    }
102	
103	    @Override
104	    public void onImportUserFromLDAP(LDAPObject ldapUser, UserModel user, RealmModel realm, boolean isCreate) {
105	
106	    }
107	
108	    @Override
109	    public UserModel proxy(LDAPObject ldapUser, UserModel delegate, RealmModel realm) {
110	        // Don't update attribute in LDAP later. It's supposed to be written just at registration time
111	        String ldapAttrName = mapperModel.get(LDAP_ATTRIBUTE_NAME);
112	        ldapUser.addReadOnlyAttributeName(ldapAttrName);
113	
114	        return delegate;
115	    }
116	
117	    @Override
118	    public void beforeLDAPQuery(LDAPQuery query) {
119	
120	    }
121	}
